 "content": "from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
