            ns=[grid[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w]
            counts=Counter(ns)
            dominant,n=counts.most_common(1)[0]
            if n>=2 and dominant!=v:
                out[r][c]=dominant
            elif n==0 or n==1:
                out[r][c]=bg
